    VM = AQFED.VolatilityModels
    maxVolDiff = 0.0
    maxStrikeDiff = 0.0
    for (row, ref) in zip(market, reference)
        tenor, tte, forward, z, isForward, atm, rr25, bf25, rr10, bf10 = row
        df = isForward ? 1.0 : z
        conv = VM.BrokerConvention(tte, forward, df, false, isForward)
        #smile volatilities at the 10P, 25P, ATM, 25C, 10C quotes from the market strangles, with the spline in delta
        vols = redirect_stdout(devnull) do
            convertQuotesToDeltaVols(conv, atm / 100, bf25 / 100, rr25 / 100, bf10 / 100, rr10 / 100; smileType=VM.SplineDeltaSmile)
        end
        y(isCall, delta, vol) = logmoneynessForDelta(VM.makeStrikeConvention(isCall, false, isForward), delta, vol, tte, forward, df)
        ys = [y(false, -0.10, vols[1]), y(false, -0.25, vols[2]), vols[3]^2 * tte / 2, y(true, 0.25, vols[4]), y(true, 0.10, vols[5])]
        for i in 1:5
            maxStrikeDiff = max(maxStrikeDiff, abs(forward * exp(ys[i]) / ref[i][1] - 1))
            maxVolDiff = max(maxVolDiff, abs(100vols[i] - ref[i][2]))
        end
    end
    println("rateslib EURUSD surface: largest difference ", maxVolDiff, " vol points, ", maxStrikeDiff, " relative strike")
    @test maxStrikeDiff < 1e-6
    @test maxVolDiff < 1.5e-3 #vol points: the two splines in delta differ slightly
end
